// Inside createApi endpoints builder:

endpoints: (builder) => ({
  // Defining a basic Query (READ operation)
  getUser: builder.query({
    query: (userId) => `/users/${userId}`,
  }),

  // Defining a Query with query parameters (?sort=asc)
  getPosts: builder.query({
    query: (sortBy) => ({
      url: '/posts',
      params: { sort: sortBy }
    }),
  }),
})
